"""Summarize measured short-MF resources from immutable returned receipts."""
from pathlib import Path
import json,hashlib,sys
p=Path(sys.argv[1]).resolve();r=p/'actual_host41';case=next((r/'cases').iterdir());a=next(x for x in (r/'audit').glob('actual_*') if x.is_dir());G=2**30
read=lambda p:json.loads(p.read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def row(snapshot,path):return next(x for x in snapshot['ancestors'] if x['path']==path)
result={'case':case.name,'roles':{},'release_receipt':{'file':str(r/'audit/SLOT_RELEASE_RECEIPT.json'),'sha256':sha(r/'audit/SLOT_RELEASE_RECEIPT.json')}}
for folder in sorted(x for x in a.iterdir() if x.is_dir()):
 d=read(folder/'RESOURCE_OBSERVATIONS.json');pre=read(folder/'PREFLIGHT.json')['cgroup']['snapshot'];rep=read(case/'tracks'/folder.name/'REPORT.json');ss=[x['cgroup'] for x in d['samples'] if 'cgroup' in x]+[d['final_snapshot']];parent=[row(s,'/user.slice') for s in ss];session=[row(s,s['membership']) for s in ss];usage=read(case/'controls'/folder.name/'PROCESS_USAGE.json');base=row(pre,'/user.slice')
 result['roles'][folder.name]={'maxrss_gib':usage['maxrss_kib']/2**20,'session_peak_gib':max(x['peak_bytes'] for x in session)/G,'session_initial_gib':row(pre,pre['membership'])['current_bytes']/G,'session_sample_current_peak_gib':max(x['current_bytes'] for x in session)/G,'parent_initial_gib':base['current_bytes']/G,'parent_sample_current_peak_gib':max(x['current_bytes'] for x in parent)/G,'parent_rawhigh_min_gib':min(x['headroom_bytes']['high'] for x in parent)/G,'parent_rawmax_min_gib':min(x['headroom_bytes']['max'] for x in parent)/G,'parent_PSI_some_avg10_range':[min(x['pressure']['some']['avg10'] for x in parent),max(x['pressure']['some']['avg10'] for x in parent)],'parent_PSI_stall_total_delta_us':parent[-1]['pressure']['some']['total']-base['pressure']['some']['total'],'parent_OOM_event_deltas':{k:parent[-1]['events'].get(k,0)-base['events'].get(k,0) for k in ['oom','oom_kill','oom_group_kill']},'tracking_s':rep['tracking_seconds'],'tracker_wall_s':rep['wall_seconds'],'gpu_peak_allocated_gib':rep['peak_allocated_bytes']/G,'gpu_peak_reserved_gib':rep['peak_reserved_bytes']/G,'report':{'file':str(case/'tracks'/folder.name/'REPORT.json'),'sha256':sha(case/'tracks'/folder.name/'REPORT.json')}}
out=p/'RESOURCE_SUMMARY_COMPACT.json';out.write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'file':str(out),'sha256':sha(out),'roles':{k:{kk:vv for kk,vv in v.items() if kk not in ['report']} for k,v in result['roles'].items()}}))
